ortadas":[],"notas":"Multi-molecular: NP (0.5-3%) + AP (0.2-1%) + EOP (0.1-0.5%). Sinergismo com niacinamida comprovado.","referencias":["https://nutraceuticalbusinessreview.com/ceramides-for-skin-wellness-from-science-to-formulation"],"uso_exportado":{"min":0.5,"max":3,"aproveitado":true}},"vinculos":[]},{"nome":"Postbiótico de Lactobacillus","nome_inci":"Lactobacillus ferment lysate","outros_nomes":[],"descricao":"Fermentado de Lactobacillus — postbiótico não-viável. Meta-análise 2026: reduziram 49.5% de lesões de acne vs 45.2% de probióticos vivos. Melhor estabilidade em formulação.","mecanismo_acao":"Modula microbioma cutâneo\nReforça defesas naturais\nInibe Cutibacterium acnes\nReduz biofilme bacteriano\nAumenta síntese de colágeno\nModula resposta imunológica","concentracao_minima":1,"concentracao_maxima":10,"ph_minimo":3,"ph_maximo":8,"solubilidade":"Água","metadados":{"fonte":"export biblioteca:actives","revisado":false,"categoria":"hidratante","origem":"biotecnologico","tags":["probiotico","microbioma","acne","postbiotico"],"indicacoes":["Acne","Disbiose cutânea","Inflamação","Microbioma desequilibrado","Sensibilidade"],"contraindicacoes_exportadas":[],"notas":"Postbióticos preferíveis a probióticos vivos. Pesquisa 2026: mais eficazes na redução de acne.","referencias":["https://www.mdpi.com/2079-9284/13/1/43","https://pmc.ncbi.nlm.nih.gov/articles/PMC13084527/"],"uso_exportado":{"min":1,"max":10,"aproveitado":true}},"vinculos":[]},{"nome":"Ácido Hialurônico Multi-Molecular","nome_inci":"Hyaluronic Acid (Multi-MW)","outros_nomes":[],"descricao":"Multi-molecular weight: ULMW penetra derme, MW médio atinge epiderme, High MW forma filme. Retém até 1000x seu peso em água. Trend 2026 de hidratação profunda.","mecanismo_acao":"Alto MW: Filme oclusivo na superfície\nMédio MW: Penetra epiderme\nBaixo MW: Atinge derme\nULMW: Máxima penetração\nSinergismo com niacinamida e ceramidas","concentracao_minima":0.5,"concentracao_maxima":2,"ph_minimo":3,"ph_maximo":8,"solubilidade":"Água","metadados":{"fonte":"export biblioteca:actives","revisado":false,"categoria":"hidratante","origem":"biotecnologico","tags":["acido-hialuronico","hidratante","anti-idade","multi-molecular"],"indicacoes":["Desidratação","Envelhecimento","Linhas finas","Perda de elasticidade","Ressecamento"],"contraindicacoes_exportadas":[],"notas":"Combinar 2-3 pesos moleculares para resultado otimizado. Usar com niacinamida e ceramidas.","referencias":["https://inspecsolutions.com/hyaluronic-acid-molecular-weight-skincare-formulation/"],"uso_exportado":{"min":0.5,"max":2,"aproveitado":true}},"vinculos":[]},{"nome":"Niacinamida (Vitamina B3)","nome_inci":"Niacinamide","outros_nomes":[],"descricao":"Vitamina B3 hidrossolúvel com múltiplas funções na epiderme. Aumenta síntese de ceramidas, colágeno e queratina. Melhora barreira cutânea, reduz inflamação e controla produção sebácea. Tolerável para todos os tipos de pele.","mecanismo_acao":"Aumenta síntese de ceramidas (40%) e colágeno (35%)\nReduz perda transepidérmica de água (TEWL)\nInibe lipase bacteriana (Propionibacterium acnes)\nReduz citocinas inflamatórias (TNF-α, IL-6, IL-8)\nModula produção de sebo via regulação de lipase","concentracao_minima":2,"concentracao_maxima":10,"ph_minimo":null,"ph_maximo":null,"solubilidade":"Água","metadados":{"fonte":"export biblioteca:actives","revisado":false,"categoria":"antioxidante","origem":"biotecnologico","tags":["niacinamida","vitamina-b3","barreira","acne","anti-idade","hidratante","anti-inflamatorio","sebo","colágeno"],"indicacoes":["Acne","barreira comprometida","dermatite","envelhecimento","hiperpigmentação","inflamação crônica","oleosidade","perda de elasticidade","rosácea"],"contraindicacoes_exportadas":[],"notas":"Combinações sinérgicas: ácido hialurônico (hidratação), ceramidas (barreira), retinol (anti-idade), ácido salicílico (acne). Evitar combinar com niacina pura (causa flushing). Concentração ótima: 5% para melhor relação custo-benefício.","referencias":["DOI:10.1111/ics.12571","DOI:10.1111/1346-8138.14584","DOI:10.1016/j.jaad.2013.12.037","PMID:22699031"],"uso_exportado":{"min":2,"max":10,"aproveitado":true},"gestacao":"liberado"},"vinculos":[]}]$gn$::jsonb) AS x(
    nome TEXT, nome_inci TEXT, outros_nomes TEXT[], descricao TEXT, mecanismo_acao TEXT,
    concentracao_minima NUMERIC, concentracao_maxima NUMERIC, ph_minimo NUMERIC, ph_maximo NUMERIC,
    solubilidade TEXT, metadados JSONB, vinculos TEXT[]
  );

  WITH inseridos AS (
    INSERT INTO public.ativos_cosmeticos (
      tenant_id, nome, nome_inci, outros_nomes, descricao, mecanismo_acao,
      status_epistemico, nivel_acesso, concentracao_minima, concentracao_maxima,
      unidade_concentracao, ph_minimo, ph_maximo, solubilidade, metadados
    )
    SELECT v_tenant, i.nome, i.nome_inci, COALESCE(i.outros_nomes, '{}'), i.descricao, i.mecanismo_acao,
           'em_observacao', 'privado', i.concentracao_minima, i.concentracao_maxima,
           '%', i.ph_minimo, i.ph_maximo, i.solubilidade, i.metadados
      FROM _ativos_import i
     WHERE NOT EXISTS (
       SELECT 1 FROM public.ativos_cosmeticos a
        WHERE a.tenant_id = v_tenant
          AND lower(unaccent(a.nome)) = lower(unaccent(i.nome))
     )
    RETURNING id, nome
  )
  INSERT INTO public.ativo_contraindicacoes (ativo_id, contraindicacao_id)
  SELECT ins.id, c.id
    FROM inseridos ins
    JOIN _ativos_import i ON i.nome = ins.nome
    CROSS JOIN LATERAL unnest(COALESCE(i.vinculos, '{}')) AS v(nome_contra)
    JOIN public.contraindicacoes_cosmeticas c ON c.nome = v.nome_contra
  ON CONFLICT DO NOTHING;

  SELECT count(*) INTO v_novos FROM public.ativos_cosmeticos
   WHERE tenant_id = v_tenant AND metadados->>'fonte' = 'export biblioteca:actives';
  RAISE NOTICE 'Ativos importados neste tenant (total da fonte): %', v_novos;
END;
$$;
